CREATE TABLE IF NOT EXISTS gis_phase360_authoritative_crosswalk (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, authoritative_source_id TEXT NOT NULL, feature_id TEXT NOT NULL, state_code TEXT, geometry_valid BOOLEAN NOT NULL DEFAULT false, match_status TEXT NOT NULL, match_score DOUBLE PRECISION NOT NULL DEFAULT 0, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,authoritative_source_id,feature_id));